export type ParsedProcessBillingInstruction<
  TProgram extends string = typeof RECORA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    sub: TAccountMetas[0];
    plan: TAccountMetas[1];
    charge: TAccountMetas[2];
    vault: TAccountMetas[3];
    subscriberAta: TAccountMetas[4];
    delegate: TAccountMetas[5];
    caller: TAccountMetas[6];
    merchantAuthority: TAccountMetas[7];
    mint: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
    tokenProgram: TAccountMetas[10];
  };
  data: ProcessBillingInstructionData;
};

export function parseProcessBillingInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedProcessBillingInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      sub: getNextAccount(),
      plan: getNextAccount(),
      charge: getNextAccount(),
      vault: getNextAccount(),
      subscriberAta: getNextAccount(),
      delegate: getNextAccount(),
      caller: getNextAccount(),
      merchantAuthority: getNextAccount(),
      mint: getNextAccount(),
      systemProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getProcessBillingInstructionDataDecoder().decode(instruction.data),
  };
}
